        for cache_type, capacity in CACHE_CAPACITY.items(): 
            self.free_blocks[cache_type] = [(0, capacity)] 
            self.allocated_blocks[cache_type] = [] 

    def allocate_address(self, size, cache_type): 
        if cache_type not in self.free_blocks: 
            return -1 
        free_list = self.free_blocks[cache_type] 
        for i, (start, block_size) in enumerate(free_list): 
            if block_size >= size: 
                new_start = start 
                new_size = block_size - size 
                if new_size > 0: 
                    free_list[i] = (start + size, new_size) 
                else: 
                    del free_list[i] 
                return start 
        return -1 

